// Generated by scripts/split-frontend.js.

// ===== L428-L510 init / loadData =====

async function init() {
  bindDelegatedEvents();
  if (!state.token) {
    renderLogin();
    return;
  }

  try {
    const me = await api("/api/auth/me");
    state.user = me.user;
    await loadData();
    if (typeof initNotificationSocket === "function") initNotificationSocket();
    renderApp();
  } catch {
    localStorage.removeItem("lan_system_token");
    state.token = "";
    renderLogin();
  }
}

async function loadData() {
  const firstPage = "limit=20&offset=0";
  const requests = state.user.role === "admin" || state.user.role === "owner"
    ? [
        api("/api/dashboard/summary"),
        api("/api/dashboard/post-type-distribution"),
        api("/api/rankings?type=posts"),
        api("/api/users"),
        api("/api/employees"),
        api("/api/accounts"),
        api(`/api/posts?${firstPage}`),
        api(`/api/leads?${firstPage}`),
        api("/api/analytics/snapshots")
      ]
    : [
        Promise.resolve(null),
        Promise.resolve([]),
        Promise.resolve([]),
        Promise.resolve([]),
        Promise.resolve([]),
        api("/api/accounts"),
        api(`/api/posts?${firstPage}`),
        api(`/api/leads?${firstPage}`),
        Promise.resolve({ snapshots: {} })
      ];
  const normalizedRequests = state.user.role === "sales"
    ? [
        Promise.resolve(null),
        Promise.resolve([]),
        Promise.resolve([]),
        Promise.resolve([]),
        Promise.resolve([]),
        api("/api/accounts"),
        api(`/api/posts?${firstPage}`),
        api(`/api/leads?${firstPage}`),
        Promise.resolve({ snapshots: {} }),
        api("/api/notifications")
      ]
    : state.user.role === "academic"
      ? [
          Promise.resolve(null),
          Promise.resolve([]),
          Promise.resolve([]),
          api("/api/users").catch(() => []),
          Promise.resolve([]),
          Promise.resolve([]),
          Promise.resolve([]),
          Promise.resolve([]),
          Promise.resolve({ snapshots: {} }),
          api("/api/notifications").catch(() => ({ items: [], unreadCount: 0 }))
        ]
      : [...requests, api("/api/notifications")];

  const [summary, distribution, rankings, users, employees, accounts, posts, leads, analyticsSnapshots, notifications] = await Promise.all(normalizedRequests);
  const postsPage = Array.isArray(posts) ? { items: posts, total: posts.length } : posts;
  const leadsPage = Array.isArray(leads) ? { items: leads, total: leads.length } : leads;
  state.summary = summary;
  state.distribution = distribution;
  state.rankings = rankings;
  state.users = users || [];
  state.employees = employees;
  state.accounts = accounts;
  state.posts = postsPage?.items || [];
  state.postTotal = Number(postsPage?.total || state.posts.length);
  state.leads = leadsPage?.items || [];
  state.leadTotal = Number(leadsPage?.total || state.leads.length);
  state.analyticsSnapshots = analyticsSnapshots.snapshots || {};
  state.notifications = notifications?.items || [];
  state.unreadNotificationCount = Number(notifications?.unreadCount || 0);
  alignStateDatesToAvailableData();
  state.teamPosts = state.posts;
  state.teamLeads = state.leads;
  state.staffLearningPostIds = state.user.role === "staff" ? await loadFavoritePostIds() : [];
  state.salesLeadLocalProfiles = state.user.role === "sales" ? loadSalesLeadLocalProfiles() : {};
  state.salesTomorrowFollowupIds = state.user.role === "sales" ? loadSalesTomorrowFollowupIds() : [];
  state.leadTomorrowFollowups = undefined; // 让 renderApp 触发 loadTomorrowFollowups 拉 next_follow_time
  if (state.user.role === "admin" || state.user.role === "owner") {
    state.reviewHighlights = loadReviewCollection("review_highlights");
    state.reviewSamples = loadReviewCollection("review_samples");
  }
}


// ===== L511-L575 renderLogin =====
function renderLogin() {
  const isOwnerPortal = window.location.port === "3001";
  const title = isOwnerPortal ? "总后台入口" : "运营协作中台";
  const subtitle = isOwnerPortal
    ? "查看整体经营、主管管理和销售推进。"
    : "统一管理员工、账号、作品和客资。";
  const bullets = isOwnerPortal
    ? ["总后台登录", "适合负责人查看全局"]
    : ["运营、主管、销售共用一套数据", "登录后直接进入对应工作台"];
  app.innerHTML = `
    <div class="login-shell">
      <div class="login-layout">
        <section class="login-aside">
          <span class="login-kicker">${isOwnerPortal ? "总后台" : "运营管理"}</span>
          <h1>${title}</h1>
          <p>${subtitle}</p>
          <div class="login-bullets">
            ${bullets.map((item) => `
              <div class="login-bullet">
                <span class="login-bullet-dot"></span>
                <span>${item}</span>
              </div>
            `).join("")}
          </div>
        </section>
        <form class="login-card" id="loginForm">
          <div class="login-card-head">
            <div>
              <h2>${isOwnerPortal ? "登录总后台" : "登录工作台"}</h2>
              <p class="muted">${isOwnerPortal ? "请输入账号和密码。" : "请输入账号和密码。"}</p>
            </div>
            <span class="login-port-tag">${isOwnerPortal ? "3001" : "3000"}</span>
          </div>
          <div class="login-fields">
            <input name="username" placeholder="用户名" required />
            <input name="password" type="password" placeholder="密码" required />
          </div>
          <button class="primary login-submit" type="submit">登录</button>
        </form>
      </div>
    </div>
  `;

  document.getElementById("loginForm").addEventListener("submit", async (event) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    try {
      const data = await api("/api/auth/login", {
        method: "POST",
        body: JSON.stringify({
          username: String(formData.get("username")).trim(),
          password: String(formData.get("password")).trim()
        })
      });
      state.token = data.token;
      state.user = data.user;
      localStorage.setItem("lan_system_token", state.token);
      await loadData();
      if (typeof initNotificationSocket === "function") initNotificationSocket();
      renderApp();
    } catch (error) {
      alert(error.message);
    }
  });
}

